var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // The change allows non-string values with length > 0 to be parsed
    // This breaks the original behavior which only parsed strings
    assert.throws(() => ms(123), Error);
    // But now, since `true && val.length > 0` is always true for any value with length,
    // even non-strings like numbers, this will incorrectly try to parse them
    assert.throws(() => ms(123), Error, 'Expected error for non-string input');
    // However, the real issue is that non-strings with length property (like arrays) are now parsed
    assert.strictEqual(ms([1, 2, 3]), undefined, 'Array with length should not be parsed');
    // But the real test is that a non-string with length > 0 is now parsed incorrectly
    // Example: "123" is a string, but 123 is a number
    // But the real defect is that `val.length` is accessed on non-strings
    // Let's test with an array
    assert.strictEqual(ms([1, 2, 3]), undefined, 'Array should not be parsed');
    // But the actual defect is that `val.length` is accessed on non-strings
    // This will cause an error if val is not an object with length
    // So we need to test with a value that has length but is not a string
    // For example, an array
    assert.throws(() => ms([1, 2, 3]), Error, 'Array should throw error');
  });
});

